 readOnly: false, render: (studentData) => <span class="status-badge status-${studentData.status}">${studentData.status}</span> }, { key: 'category', label: 'קטגוריה', sortable: true, readOnly: false, render: (studentData) => <span class="category-badge">${studentData.category}</span> }, { key: 'actions', label: 'פעולות', sortable: false, readOnly: true, render: (studentData) => <div class="actions-cell"> <button class="btn btn-sm btn-icon" onclick="viewStudentDetails('${studentData.id}')" title="צפייה"> <img src="view_icon.png" alt="צפייה" class="action-icon-natural"> </button> <button class="btn btn-sm btn-icon" onclick="editStudentDetails('${studentData.id}')" title="עריכה"> <img src="edit_icon.png" alt="עריכה" class="action-icon-natural"> </button> </div> } ]; try { const studentsTable = new ReusableTable('studentsTableContainer', { tableName: 'students', isReadOnly: false, allowAdd: true, allowEdit: true, allowDelete: false }); studentsTable.init(data, columns); studentsTable.onSave = (updatedData) => { window.currentStudentsData = updatedData; }; console.log('✅ Students ReusableTable initialized successfully with', data.length, 'students'); } catch (error) { console.error('❌ Error creating students ReusableTable:', error); showStudentsTableError('שגיאה ביצירת טבלת התלמידים'); } } // Add missing student action functions following Frontend Architecture Patterns function viewStudentDetails(studentId) { console.log('👁️ Viewing student details:', studentId); const studentData = getStudentById(studentId); if (studentData) { // Store in session following Authentication & Session Management sessionStorage.setItem('selectedStudentId', studentId); sessionStorage.setItem('selectedStudentName', studentData.name); // Show student details in modal or navigate to student page alert(פרטי התלמיד:
