>Status</th> <th>סה"כ נדרש</th> <th>Last update</th> <th>פעולות</th> </tr> </thead> <tbody> ${councils.map(council => <tr> <td><strong>${council.council || ''}</strong></td> <td>${council.numberOfStudents || '0'}</td> <td> <span class="status-badge status-${council.status ? council.status.replace(/\s+/g, '-').toLowerCase() : 'unknown'}"> ${council.status || 'Unknown'} </span> </td> <td>${council.totalRequested || '-'}</td> <td>${council.lastUpdate || '-'}</td> <td class="actions-cell"> <button class="btn btn-sm btn-icon" onclick="viewCouncil(${council.id})" title="צפייה ברשות"> <img src="view_icon.png" alt="צפייה" class="action-icon-natural"> </button> </td> </tr> ).join('')} </tbody> </table> </div> ; container.innerHTML = tableHTML; console.log('✅ Simple table created with', councils.length, 'councils'); } // Create empty table when no data available function createEmptyTable() { console.log('📊 Creating empty table'); const container = document.getElementById('councilsTableContainer'); if (!container) return; const tableHTML = <div class="table-container"> <table class="data-table"> <thead> <tr> <th>רשות</th> <th>מספר תלמידים</th> <th>Status</th> <th>סה"כ נדרש</th> <th>Last update</th> <th>פעולות</th> </tr> </thead> <tbody> <tr> <td colspan="6" style="text-align: center; padding: 40px; color: #6c757d;"> אין נתוני רשויות זמינים </td> </tr> </tbody> </table> </div> ; container.innerHTML = tableHTML; console.log('✅ Empty table created'); } // Council management function following Cross-Component Communication function viewCouncil(councilId) { console.log('👁️ Viewing council:', councilId); const council = allCouncils.find(c => c.id === councilId); if (council) { // Store selected council information in session following Authentication & Session Management sessionStorage.setItem('selectedCouncilId', councilId); sessionStorage.setItem('selectedCouncilName', council.council); console.log('Selected council stored:', { id: councilId, name: council.council }); // For now, show a simple alert - this can be extended to navigate to a detailed view alert(צפייה ברשות: ${council.council}
