.focus(); // Log document access following Critical Development Workflows console.log(📄 Document accessed: ID=${documentData.id}, Form="${documentData.form}", Status="${documentData.status}"); } else { // Handle popup blocker following Hebrew/RTL Specific Patterns console.warn('⚠️ Could not open document - popup may be blocked'); showDocumentAccessOptions(documentData, fullDocumentUrl); } } catch (error) { console.error('❌ Error opening document:', error); alert(שגיאה בפתיחת המסמך "${documentData.form}":
